<section class="panel form-panel"><h2>Inviter une personne</h2><p class="muted">Le destinataire choisit son mot de passe via un lien valable 48 heures. @if(config('psycho.mail_delivery')==='local')<a class="text-link" href="/administration/boite-test">Ouvrir la boîte locale de test ↗</a>@endif</p><form method="post" action="/administration/invitations">@csrf<div class="form-grid"><label>Nom<input name="name" required maxlength="100"></label><label>E-mail<input name="email" type="email" required></label><label>Rôle<select name="role">@foreach(['patient','entreprise','conseiller','psychologue','admin'] as $role)<option>{{ $role }}</option>@endforeach</select></label><label>Dossier patient<select name="client_id"><option value="">Sans dossier</option>@foreach($clients->whereNull('user_id') as $client)<option value="{{ $client->id }}">{{ $client->full_name }}</option>@endforeach</select></label><label>Organisation<select name="organization_id"><option value="">Sans organisation</option>@foreach($organizations as $organization)<option value="{{ $organization->id }}">{{ $organization->name }}</option>@endforeach</select></label></div><button class="btn primary">Préparer l’invitation</button></form>@foreach($invitations as $invitation)<div class="list-row"><span class="grow">{{ $invitation->user->email }} · {{ $invitation->expires_at->isPast() ? 'Expirée ou révoquée' : 'En attente' }}</span><form method="post" action="/administration/invitations/{{ $invitation->id }}/renvoyer">@csrf<button class="btn secondary small">Renvoyer</button></form><form method="post" action="/administration/invitations/{{ $invitation->id }}/revoquer">@csrf<button class="btn danger small">Révoquer</button></form></div>@endforeach</section>
<section class="panel form-panel"><h2>Modifier les rôles</h2><p class="muted">Chaque modification ferme les anciennes sessions. Votre propre rôle est protégé.</p>@foreach($users->where('id','!=',auth()->id()) as $user)<details><summary>{{ $user->name }} · {{ $user->role }}</summary><form method="post" action="/administration/utilisateurs/{{ $user->id }}/role" data-confirm="Modifier les droits de cette personne et fermer ses sessions ?">@csrf @method('PUT')<div class="form-grid"><label>Rôle<select name="role">@foreach(['patient','entreprise','conseiller','psychologue','admin'] as $role)<option @selected($user->role===$role)>{{ $role }}</option>@endforeach</select></label><label>Dossier patient<select name="client_id"><option value="">Sans dossier</option>@foreach($clients->filter(fn($c)=>!$c->user_id || $c->user_id===$user->id) as $client)<option value="{{ $client->id }}" @selected($client->user_id===$user->id)>{{ $client->full_name }}</option>@endforeach</select></label><label>Organisation<select name="organization_id"><option value="">Sans organisation</option>@foreach($organizations as $organization)<option value="{{ $organization->id }}" @selected($user->organization_id===$organization->id)>{{ $organization->name }}</option>@endforeach</select></label></div><button class="btn secondary">Modifier les droits</button></form></details>@endforeach</section>